<?php require_once __DIR__ . '/auth.php'; $leads=load_json(LEADS_FILE,[]);
if(isset($_GET['download']) && $_GET['download']==='csv'){ header('Content-Type:text/csv; charset=utf-8'); header('Content-Disposition: attachment; filename=leads.csv'); $o=fopen('php://output','w'); fputcsv($o,['id','name','whatsapp','property_type','created_at']); foreach($leads as $l){fputcsv($o,[$l['id']??'',$l['name']??'',$l['whatsapp']??'',$l['property_type']??'',$l['created_at']??'']);} fclose($o); exit; }
?><!doctype html><html><head><meta charset='utf-8'><link rel='stylesheet' href='../assets/bootstrap/css/bootstrap.min.css'><title>Leads</title></head><body class='container'><h3>Leads recebidos</h3><a href='dashboard.php'>← Dashboard</a> <a class='btn btn-success btn-sm' href='?download=csv'>Baixar CSV</a><table class='table table-bordered'><tr><th>ID</th><th>Nome</th><th>WhatsApp</th><th>Tipo</th><th>Data</th></tr><?php foreach(array_reverse($leads) as $l):?><tr><td><?=e($l['id']??'')?></td><td><?=e($l['name']??'')?></td><td><?=e($l['whatsapp']??'')?></td><td><?=e($l['property_type']??'')?></td><td><?=e($l['created_at']??'')?></td></tr><?php endforeach;?></table></body></html>
